import React, { useState } from 'react';
import axios from 'axios';

const MassSalaryPayment = () => {
  const [paymentMethod, setPaymentMethod] = useState('cash');
  const [paymentFromDate, setPaymentFromDate] = useState('');
  const [paymentToDate, setPaymentToDate] = useState('');
  const [status, setStatus] = useState('pending');
  const [message, setMessage] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setMessage('');

    const payload = {
      paymentMethod,
      paymentFromDate,
      paymentToDate,
      status,
    };
    const token = localStorage.getItem('token')
    
    try {
      const response = await axios.post('https://apartment.houseethiopia.com/api/salary-payments/mass-pay', payload, {
        headers : {Authorization: `Bearer ${token}`,}
      },);
      setMessage(`Success: ${response.data.message} (${response.data.successfulPayments} successful payments)`);
    } catch (error) {
      setMessage(`Error: ${error.response ? error.response.data.message : 'Something went wrong'}`);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="max-w-lg mx-auto mt-10 p-6 bg-white shadow-lg rounded-lg">
      <h2 className="text-2xl font-bold mb-4">Mass Salary Payment</h2>
      <form onSubmit={handleSubmit} className="space-y-4">
        {/* Payment Method */}
        <div>
          <label htmlFor="paymentMethod" className="block text-sm font-medium text-gray-700">
            Payment Method
          </label>
          <select
            id="paymentMethod"
            value={paymentMethod}
            onChange={(e) => setPaymentMethod(e.target.value)}
            className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
          >
            <option value="cash">Cash</option>
            <option value="bank">Bank</option>
          </select>
        </div>

        {/* Payment From Date */}
        <div>
          <label htmlFor="paymentFromDate" className="block text-sm font-medium text-gray-700">
            Payment From Date
          </label>
          <input
            type="datetime-local"
            id="paymentFromDate"
            value={paymentFromDate}
            onChange={(e) => setPaymentFromDate(e.target.value)}
            className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
            required
          />
        </div>

        {/* Payment To Date */}
        <div>
          <label htmlFor="paymentToDate" className="block text-sm font-medium text-gray-700">
            Payment To Date
          </label>
          <input
            type="datetime-local"
            id="paymentToDate"
            value={paymentToDate}
            onChange={(e) => setPaymentToDate(e.target.value)}
            className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
            required
          />
        </div>

        {/* Status */}
        <div>
          <label htmlFor="status" className="block text-sm font-medium text-gray-700">
            Status
          </label>
          <select
            id="status"
            value={status}
            onChange={(e) => setStatus(e.target.value)}
            className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
          >
            <option value="pending">Pending</option>
            <option value="completed">Completed</option>
          </select>
        </div>

        {/* Submit Button */}
        <div>
          <button
            type="submit"
            disabled={isLoading}
            className={`w-full py-2 px-4 bg-blue-500 text-white rounded-md hover:bg-blue-600 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 ${isLoading ? 'opacity-50 cursor-not-allowed' : ''}`}
          >
            {isLoading ? 'Processing...' : 'Submit Payment'}
          </button>
        </div>
      </form>

      {/* Response Message */}
      {message && (
        <div className="mt-4 text-sm text-gray-700">
          <p>{message}</p>
        </div>
      )}
    </div>
  );
};

export default MassSalaryPayment;
